<template><page-section title="页面结构回放"><el-empty v-if="!step" description="请选择一个执行步骤" /><template v-else><div class="replay-head"><span>步骤 {{ step.step_no }} · {{ step.instruction || step.action_type || '-' }}</span><el-tag size="mini" :type="step.status==='success'?'success':'info'">{{ step.status || '-' }}</el-tag></div><el-row :gutter="16"><el-col :span="12"><div class="panel-title">操作前 / 后截图</div><div class="image-grid"><artifact-image v-if="step.before_screenshot_artifact_id" :artifact-id="step.before_screenshot_artifact_id" title="操作前" /><artifact-image v-if="step.after_screenshot_artifact_id" :artifact-id="step.after_screenshot_artifact_id" title="操作后" /><span v-if="!step.before_screenshot_artifact_id&&!step.after_screenshot_artifact_id" class="muted">暂无步骤截图</span></div></el-col><el-col :span="12"><div class="panel-title">定位与页面结构</div><div class="meta"><b>定位策略：</b>{{ step.locator_strategy || '-' }}</div><pre>{{ json(step.target_element || {}) }}</pre><pre>{{ json(step.page_snapshot || {}) }}</pre></el-col></el-row><div v-if="step.error_message" class="error"><b>错误：</b>{{ step.error_message }}</div></template></page-section></template>
<script>
import PageSection from '@/components/TestPlatform/common/PageSection'
import { previewMobileArtifact } from '@/api/mobileAutomationApi'
const ArtifactImage={props:{artifactId:[String,Number],title:String},data(){return {url:'',loading:false}},watch:{artifactId:{immediate:true,handler(){this.load()}}},beforeDestroy(){if(this.url)URL.revokeObjectURL(this.url)},methods:{load(){if(!this.artifactId)return;this.loading=true;previewMobileArtifact(this.artifactId).then(blob=>{if(this.url)URL.revokeObjectURL(this.url);this.url=URL.createObjectURL(blob)}).finally(()=>{this.loading=false})}},template:'<div class="artifact-image"><div>{{ title }}</div><i v-if="loading" class="el-icon-loading" /><img v-else-if="url" :src="url" :alt="title" /></div>'}
export default{name:'MobileAutomationPageReplay',components:{PageSection,ArtifactImage},props:{step:{type:Object,default:null}},methods:{json(v){return JSON.stringify(v,null,2)}}}
</script><style scoped>.replay-head{display:flex;justify-content:space-between;margin-bottom:14px}.panel-title{font-weight:600;margin-bottom:8px}.image-grid{display:flex;gap:12px;flex-wrap:wrap}.artifact-image{max-width:100%;color:#606266}.artifact-image img{display:block;margin-top:6px;max-width:100%;max-height:430px;border:1px solid #ebeef5}.meta{margin-bottom:8px}pre{max-height:260px;overflow:auto;padding:10px;background:#f5f7fa;border-radius:4px;font-size:12px}.muted{color:#909399}.error{margin-top:14px;color:#f56c6c}</style>
